import React, { useState, useEffect } from 'react';
import Icon from 'components/AppIcon';
import api from '../../lib/api';
import LoadingState from '../../components/ui/LoadingState';

const LeaderboardPage = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [sortBy, setSortBy] = useState('elo'); // 'elo' or 'hours'

  useEffect(() => {
    setLoading(true);
    api.getLeaderboard(sortBy)
      .then(setData)
      .finally(() => setLoading(false));
  }, [sortBy]);

  const { leaderboard = [], yourRank } = data || {};

  return (
    <div className="min-h-screen bg-background">
      <div className="container mx-auto px-4 py-8 max-w-3xl">
        <div className="mb-8 flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <h1 className="text-2xl lg:text-3xl font-heading font-bold text-text-primary">Leaderboard</h1>
            <p className="text-text-secondary mt-1">
              Compete anonymous-style · Your rank: {yourRank ? `#${yourRank}` : 'Unranked'}
            </p>
          </div>

          {/* Toggle Tabs */}
          <div className="flex bg-surface border border-border p-1 rounded-full shadow-warm-sm">
            <button
              onClick={() => setSortBy('elo')}
              className={`flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-full transition-all duration-200 ${
                sortBy === 'elo'
                  ? 'bg-primary text-white shadow-md'
                  : 'text-text-secondary hover:text-text-primary'
              }`}
            >
              <Icon name="Award" size={16} />
              <span>Competitive (ELO)</span>
            </button>
            <button
              onClick={() => setSortBy('hours')}
              className={`flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-full transition-all duration-200 ${
                sortBy === 'hours'
                  ? 'bg-primary text-white shadow-md'
                  : 'text-text-secondary hover:text-text-primary'
              }`}
            >
              <Icon name="Clock" size={16} />
              <span>Grit (Hours)</span>
            </button>
          </div>
        </div>

        {loading ? (
          <LoadingState message="Updating rankings..." />
        ) : (
          <div className="card overflow-hidden border border-border shadow-warm-lg rounded-xl bg-surface">
            {/* Table Header */}
            <div className="grid grid-cols-12 gap-2 p-4 bg-surface-50 text-xs font-semibold text-text-secondary border-b border-border uppercase tracking-wider">
              <div className="col-span-1">#</div>
              <div className="col-span-4">Learner</div>
              <div className="col-span-2 text-right">ELO</div>
              <div className="col-span-2 text-right">Hours</div>
              <div className="col-span-1 text-right">Streak</div>
              <div className="col-span-2 text-right">Level</div>
            </div>

            {/* Table Rows */}
            {leaderboard.map((entry) => (
              <div
                key={entry.userId}
                className="grid grid-cols-12 gap-2 p-4 border-b border-border-light items-center hover:bg-surface-50 transition-colors"
              >
                <div className="col-span-1 font-bold text-primary">{entry.rank}</div>
                <div className="col-span-4 flex items-center gap-2">
                  {entry.rank <= 3 && (
                    <Icon
                      name="Trophy"
                      size={16}
                      className={
                        entry.rank === 1
                          ? 'text-warning'
                          : entry.rank === 2
                            ? 'text-text-secondary'
                            : 'text-accent'
                      }
                    />
                  )}
                  <span className="font-medium text-text-primary">{entry.name}</span>
                </div>
                <div className="col-span-2 text-right font-bold text-accent">{entry.elo || 1000}</div>
                <div className="col-span-2 text-right text-text-secondary">
                  {Number(entry.totalHours).toFixed(1)}h
                </div>
                <div className="col-span-1 text-right text-text-secondary">{entry.streak}d</div>
                <div className="col-span-2 text-right">
                  <span className="px-2 py-0.5 rounded-full text-2xs font-medium bg-primary-50 text-primary-700">
                    {entry.learningLevel}
                  </span>
                </div>
              </div>
            ))}

            {leaderboard.length === 0 && (
              <p className="p-8 text-center text-text-secondary">
                Be the first on the board — start learning!
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default LeaderboardPage;
